      if (o.budget === 'free' && t.price > 0) s -= 200;
      if (o.budget === 'low' && t.price > 300) s -= 200;
      if (o.pri === 'rated') s += Math.min(40, Math.log10(1 + t.count) * 13) + t.rating * 2;
