            h('div', { class: 'jt-actions' }, [copyB, JT.btn(T('wa.open'), { kind: 'wa', icon: 'wa', href: 'https://wa.me/' + (phone.length >= 11 ? phone : '') + '?text=' + encodeURIComponent(text), blank: true })])
